declare(strict_types=1);require __DIR__.'/bootstrap.php';if(empty($_SESSION['admin_id']))redirect('index.php');require_once dirname(__DIR__).'/private/seo.php';require_once dirname(__DIR__).'/private/ui.php';$keyword=(int)($_GET['keyword']??0);$back='seo.php?keyword='.$keyword;
if($_SERVER['REQUEST_METHOD']==='POST'){checkCsrf();try{$a=(string)($_POST['action']??'');if($a==='keyword'){$id=seoKeyword($pdo,(string)($_POST['keyword']??''),(string)($_POST['location']??''));redirect('seo.php?keyword='.$id);}elseif($a==='active'){$q=$pdo->prepare('UPDATE seo_keywords SET active=? WHERE id=?');$q->execute([empty($_POST['active'])?0:1,(int)($_POST['id']??0)]);}elseif($a==='preview'){$f=$_FILES['measurements']??[];if(($f['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_OK||!is_uploaded_file($f['tmp_name']??'')||($f['size']??0)>256*1024||strtolower(pathinfo($f['name'],PATHINFO_EXTENSION))!=='csv')throw new InvalidArgumentException('CSV-Datei maximal256KB erforderlich.');$mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);if(!in_array($mime,['text/plain','text/csv','application/csv'],true))throw new InvalidArgumentException('Nur CSV-Textdatei.');$depth=filter_var($_POST['depth']??'',FILTER_VALIDATE_INT);if($depth===false)throw new InvalidArgumentException('Messtiefe ungültig.');$token=seoPreview($pdo,(int)$_SESSION['admin_id'],(int)($_POST['keyword_id']??0),file_get_contents($f['tmp_name']),(string)($_POST['measured_at']??''),(string)($_POST['source']??''),$depth);redirect($back.'&preview='.$token);}elseif($a==='apply'){if(empty($_POST['confirm']))throw new RuntimeException('Quelle und Messdaten ausdrücklich bestätigen.');$run=seoApply($pdo,(int)$_SESSION['admin_id'],(string)($_POST['token']??''));$_SESSION['app_notice']='Messdaten importiert. Kein automatischer Google-Abruf behauptet.';redirect($back.'&run='.$run);}else throw new RuntimeException('Aktion unbekannt.');}catch(Throwable $e){gszUiError($e);}redirect($back);}
$keywords=[];$runs=[];$preview=null;$run=null;$points=[];$ready=true;
try{$keywords=$pdo->query('SELECT * FROM seo_keywords ORDER BY keyword,location LIMIT 501')->fetchAll();if(count($keywords)>500)throw new RuntimeException('Keywordlimit500 erreicht.');$q=$pdo->prepare('SELECT * FROM seo_runs WHERE keyword_id=? ORDER BY measured_at DESC,id DESC LIMIT 100');$q->execute([$keyword]);$runs=$q->fetchAll();$historyStats=[];if($runs){$ids=array_column($runs,'id');$aggregate=$pdo->prepare('SELECT run_id,COUNT(*) points,SUM(rank_position BETWEEN 1 AND 3) top3,SUM(rank_position>0) found FROM seo_points WHERE run_id IN('.implode(',',array_fill(0,count($ids),'?')).') GROUP BY run_id');$aggregate->execute($ids);foreach($aggregate->fetchAll() as $v){$v['top3_basis_points']=$v['points']?intdiv((int)$v['top3']*10000+intdiv((int)$v['points'],2),(int)$v['points']):0;$historyStats[$v['run_id']]=$v;}}if($runs){$run=$runs[0];foreach($runs as $candidate)if((int)$candidate['id']===(int)($_GET['run']??0))$run=$candidate;$points=seoPoints($pdo,(int)$run['id']);}if(isset($_GET['preview'])){$q=$pdo->prepare('SELECT * FROM seo_imports WHERE token=? AND admin_id=?');$q->execute([(string)$_GET['preview'],(int)$_SESSION['admin_id']]);$preview=$q->fetch();}}catch(Throwable $e){$ready=false;}
gszPageStart('SEO-Monitor');?><p>Live-Rankings, Search Console und Google-Unternehmensprofil: <strong>BLOCKED – keine autorisierte Quelle verbunden.</strong> Hier werden ausschließlich ausdrücklich importierte Messdaten angezeigt. Quellenangabe und Bestätigung sind kein unabhängiger Nachweis der Messung. Keine Scraping-/API-Aufrufe beim Öffnen.</p><?php if(!$ready):?><p class="error">SEO benötigt Migration350. Bestehende Daten bleiben erhalten.</p><?php else:?>
<section class="card"><h2>Keywords verwalten</h2><form method="post"><?php gszFields('keyword');?><label>Keyword<input name="keyword" maxlength="190" required placeholder="z.B. Gebäudeservice Gütersloh"></label><label>Ort/Gebiet<input name="location" maxlength="190" required></label><button>Keyword speichern</button></form><form method="get"><label>Auswertung<select name="keyword"><option value="0">Keyword wählen</option><?php foreach($keywords as $k):?><option value="<?=(int)$k['id']?>" <?=$keyword===(int)$k['id']?'selected':''?>><?=e($k['keyword'].' · '.$k['location'].($k['active']?'':' · pausiert'))?></option><?php endforeach?></select></label><button>Messhistorie anzeigen</button></form><?php foreach($keywords as $k):if((int)$k['id']!==$keyword)continue;?><form method="post"><?php gszFields('active');?><input type="hidden" name="id" value="<?=(int)$k['id']?>"><input type="hidden" name="active" value="<?=$k['active']?'':'1'?>"><button><?=$k['active']?'Keyword pausieren':'Keyword reaktivieren'?></button></form><?php endforeach?></section>
<?php if($keyword):?><section class="card"><h2>Belegbare Messdaten importieren</h2><p><a href="seo_export.php?template=1">Leere CSV-Vorlage</a>. Exakte Spalten: punkt;breitengrad;laengengrad;position;wettbewerber;wettbewerber_position. Koordinaten mit Dezimalpunkt, maximal6Nachkommastellen. Position0 bedeutet bis zur angegebenen Messtiefe nicht gefunden; leere/erfundene Rankings nicht eintragen.</p><form method="post" enctype="multipart/form-data"><?php gszFields('preview');?><input type="hidden" name="keyword_id" value="<?=$keyword?>"><label>Messzeitpunkt UTC<input type="datetime-local" name="measured_at" value="<?=e(gmdate('Y-m-d\TH:i'))?>" required></label><label>Tatsächliche Quelle / Messbeleg<input name="source" maxlength="190" required></label><label>Durchsuchte Ergebnistiefe<input name="depth" type="number" min="3" max="100" value="20" required></label><label>UTF-8-CSV, maximal121Messpunkte<input name="measurements" type="file" accept=".csv" required></label><button>Messvorschau erzeugen</button></form></section><?php endif?>
<?php if($preview):$payload=json_decode($preview['payload'],true,64,JSON_THROW_ON_ERROR);$stats=seoStats($payload['points']);?><section class="card"><h2>Messvorschau – noch nicht übernommen</h2><p><?=e($payload['source'].' · '.$payload['measured_at'])?> UTC · <?=$stats['points']?> Punkte · Top3 <?=$stats['top3']?> · <?=e(financeDecimal($stats['top3_basis_points']))?>%</p><?php if($payload['conflict']):?><p class="error">Gleiche Messidentität mit anderen Werten – Konflikt, keine Überschreibung.</p><?php endif?><?php if($payload['duplicate']):?><p>Identische Messung bereits vorhanden – keine Dublette.</p><?php endif?><form method="post"><?php gszFields('apply');?><input type="hidden" name="token" value="<?=e($preview['token'])?>"><label><input type="checkbox" name="confirm" required> Keyword, Gebiet, Zeitpunkt, Quelle, Koordinaten und Positionen tatsächlich geprüft.</label><button <?=$payload['conflict']?'disabled':''?>>Messung bestätigen</button></form></section><?php endif?>
<?php if($run):$stats=seoStats($points);$lat=array_values(array_unique(array_column($points,'latitude_e6')));$lon=array_values(array_unique(array_column($points,'longitude_e6')));rsort($lat,SORT_NUMERIC);sort($lon,SORT_NUMERIC);?><section class="card"><h2>GeoGrid – importierte Positionen</h2><p>Stand <?=e($run['measured_at'])?> UTC · Quelle <?=e($run['source'])?> · Messtiefe <?=(int)$run['search_depth']?> · extern nicht unabhängig verifiziert.</p><p>Top3: <?=$stats['top3']?>/<?=$stats['points']?> (<?=e(financeDecimal($stats['top3_basis_points']))?>%) · gefunden <?=$stats['found']?>. Grün1–3, Gelb4–10, Rot später, Grau bis Messtiefe nicht gefunden. Keine fehlenden Punkte erfinden.</p><div class="seo-grid" style="grid-template-columns:repeat(<?=count($lon)?>,minmax(38px,1fr))" aria-label="GeoGrid mit importierten Messpositionen"><?php foreach($points as $point):$rank=(int)$point['rank_position'];$row=array_search($point['latitude_e6'],$lat)+1;$col=array_search($point['longitude_e6'],$lon)+1;?><span class="seo-cell <?=$rank===0?'seo-empty':($rank<=3?'seo-top':($rank<=10?'seo-mid':'seo-low'))?>" style="grid-row:<?=$row?>;grid-column:<?=$col?>" title="<?=e($point['point_key'].' · '.($point['latitude_e6']/1000000).','.($point['longitude_e6']/1000000).' · '.($rank?:'nicht gefunden'))?>"><?=$rank?:'–'?></span><?php endforeach?></div><table><thead><tr><th>Punkt</th><th>Position</th><th>Wettbewerber</th><th>Position</th></tr></thead><tbody><?php foreach($points as $point):?><tr><td><?=e($point['point_key'])?></td><td><?=(int)$point['rank_position']?:'nicht gefunden'?></td><td><?=e($point['competitor'])?></td><td><?=e($point['competitor_rank']===null?'keine Messung':(string)$point['competitor_rank'])?></td></tr><?php endforeach?></tbody></table><a href="seo_export.php?keyword=<?=$keyword?>">Historie / Wochenbericht als CSV exportieren</a></section><?php endif?>
<section class="card"><h2>Messhistorie und Wochenvergleich</h2><?php if(!$runs):?><p>Keine importierten Messungen. Es werden keine fiktiven Rankings angezeigt.</p><?php endif?><?php foreach($runs as $h):$hs=$historyStats[$h['id']];?><p><a href="<?=e($back.'&run='.$h['id'])?>"><?=e($h['measured_at'])?> UTC</a> · <?=e($h['source'])?> · Top3 <?=e(financeDecimal($hs['top3_basis_points']))?>%</p><?php endforeach?><?php if($run):$prior=null;foreach($runs as $h)if(strtotime($h['measured_at'].' UTC')<=strtotime($run['measured_at'].' UTC')-7*86400){$prior=$h;break;}if($prior&&$prior['search_depth']===$run['search_depth']&&$prior['source']===$run['source']&&seoComparable($points,seoPoints($pdo,(int)$prior['id']))):$ps=seoStats(seoPoints($pdo,(int)$prior['id']));?><p>Vergleich mit <?=e($prior['measured_at'])?> UTC: Top3-Veränderung <?=e(financeDecimal($stats['top3_basis_points']-$ps['top3_basis_points']))?> Prozentpunkte bei gleichem Gebiet, Quelle und Messtiefe.</p><?php else:?><p>Noch keine mindestens7Tage ältere direkt vergleichbare Messung derselben Quelle/Grid/Messtiefe. Keine erfundene Ranking-Veränderung.</p><?php endif;endif?></section><?php endif;gszPageEnd();
